// Generic Gemini generateContent call. The caller (ux-interview-analysis skill) supplies
// the full request body; prompts and schemas live in the skill as versioned files.
const b = $('When Called').first().json.body || {};
for (const k of ['interview_id', 'stage', 'prompt_version', 'model']) {
  if (!b[k] || typeof b[k] !== 'string') throw new Error(`Missing/invalid field: ${k}`);
}
if (!/^[a-z0-9.\-]+$/.test(b.model)) throw new Error('model must look like gemini-x.y-name');
if (!b.request || typeof b.request !== 'object' || !Array.isArray(b.request.contents)) {
  throw new Error('request must be a generateContent body with a contents array');
}
const run_id = `${b.interview_id}-${b.stage}-${$execution.id}`;

// params_json = the request with prompt text and schema redacted (both are versioned files in the skill).
const params = JSON.parse(JSON.stringify(b.request));
for (const c of params.contents) {
  for (const p of (c.parts || [])) {
    if (typeof p.text === 'string') p.text = `<${p.text.length} chars>`;
  }
}
const gc = params.generationConfig || {};
for (const k of ['responseSchema', 'responseJsonSchema']) if (gc[k]) gc[k] = '<schema>';

return [{ json: {
  run_id,
  interview_id: b.interview_id,
  stage: b.stage,
  prompt_version: b.prompt_version,
  model: b.model,
  request: b.request,
  params_json: JSON.stringify({ model: b.model, ...params }),
} }];

// Store the model output byte-exact; never re-serialise model text.
const v = $('Validate Request').first().json;
const r = $input.first().json;
const cand = (r.candidates || [])[0] || {};
const parts = (cand.content && cand.content.parts) || [];
const texts = parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text);
const transcriptions = parts.filter(p => p.audioTranscription).map(p => p.audioTranscription);

let output;
if (transcriptions.length) output = JSON.stringify(transcriptions);
else if (texts.length) output = texts.join('');
else output = JSON.stringify(r);

const finish = cand.finishReason || 'NONE';
let status = finish === 'STOP' ? 'ok' : finish === 'MAX_TOKENS' ? 'truncated' : `finish_${String(finish).toLowerCase()}`;
const wantsJson = ((v.request.generationConfig || {}).responseMimeType) === 'application/json';
if (status === 'ok' && wantsJson && !transcriptions.length) {
  try { JSON.parse(output); } catch (e) { status = 'parse_error'; }
}
const u = r.usageMetadata || {};
return [{ json: {
  run_id: v.run_id,
  interview_id: v.interview_id,
  stage: v.stage,
  model: v.model,
  model_version: r.modelVersion || '',
  prompt_version: v.prompt_version,
  params_json: v.params_json,
  output_json: output,
  tokens_in: u.promptTokenCount ?? null,
  tokens_out: (u.candidatesTokenCount ?? 0) + (u.thoughtsTokenCount ?? 0),
  status,
} }];

// Gemini returned an HTTP error: record it as a failed run (never silently dropped).
const v = $('Validate Request').first().json;
const e = $input.first().json;
const err = e.error !== undefined ? e.error : e;
const msg = typeof err === 'object' ? JSON.stringify(err) : String(err);
return [{ json: {
  run_id: v.run_id,
  interview_id: v.interview_id,
  stage: v.stage,
  model: v.model,
  model_version: '',
  prompt_version: v.prompt_version,
  params_json: v.params_json,
  output_json: msg.slice(0, 20000),
  tokens_in: null,
  tokens_out: null,
  status: 'error',
} }];

// Last node = job result; the caller reads it from the n8n execution (job_id).
const row = $('Shape Run').isExecuted ? $('Shape Run').first().json : $('Shape Error').first().json;
return [{ json: {
  run_id: row.run_id,
  status: row.status,
  model_version: row.model_version,
  tokens_in: row.tokens_in,
  tokens_out: row.tokens_out,
  output_chars: (row.output_json || '').length,
} }];
